def choose_move(observation):
    # Defensive access with defaults
    x = observation.get("player_x", 0)
    y = observation.get("player_y", 0)

    # Prefer staying or moving to follow a simple robust heuristic
    # If there is a known target, move toward it; otherwise bounce around small area.
    target = observation.get("target", None)
    if target is None:
        # Try to use a secondary cue: best effort toward center (0,0) or nearest resource
        resources = observation.get("resources", [])
        if isinstance(resources, list) and resources:
            rx, ry = resources[0].get("x", 0), resources[0].get("y", 0)
            dx = (rx - x)
            dy = (ry - y)
        else:
            dx = 0
            dy = 0
    else:
        tx = target.get("x", 0)
        ty = target.get("y", 0)
        dx = tx - x
        dy = ty - y

    # Normalize to -1, 0, 1
    if dx > 0:
        dx = 1
    elif dx < 0:
        dx = -1
    else:
        dx = 0

    if dy > 0:
        dy = 1
    elif dy < 0:
        dy = -1
    else:
        dy = 0

    # If both dx and dy are zero (already at target), attempt a small exploration move
    if dx == 0 and dy == 0:
        # Use a simple deterministic wobble based on position parity
        if (x + y) % 2 == 0:
            return [1, 0]
        else:
            return [0, 1]

    return [dx, dy]

